import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Lesson 16: What to Learn Next","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-6/lesson-16.md","filePath":"en/modules/module-6/lesson-16.md"}'),n={name:"en/modules/module-6/lesson-16.md"};function r(l,e,s,d,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="lesson-16-what-to-learn-next" tabindex="-1">Lesson 16: What to Learn Next <a class="header-anchor" href="#lesson-16-what-to-learn-next" aria-label="Permalink to &quot;Lesson 16: What to Learn Next&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Understand advanced learning directions for Codex and plan your next steps ⏱️ <strong>Estimated Time</strong>: 15 minutes 🎯 <strong>Teaching Rhythm</strong>: Introduction + guidance</p></blockquote><hr><h2 id="i-what-have-you-learned" tabindex="-1">I. What Have You Learned? <a class="header-anchor" href="#i-what-have-you-learned" aria-label="Permalink to &quot;I. What Have You Learned?&quot;">​</a></h2><p>After completing this course, you should be able to:</p><ul><li>✅ Understand what Codex is and what it can do</li><li>✅ Install and log into the Codex desktop app</li><li>✅ Command Codex to complete File Operations using natural language</li><li>✅ Have Codex search the web and organize materials</li><li>✅ Use Codex skills to quickly complete complex tasks</li><li>✅ Independently complete a full project from requirement to delivery</li></ul><hr><h2 id="ii-advanced-learning-directions" tabindex="-1">II. Advanced Learning Directions <a class="header-anchor" href="#ii-advanced-learning-directions" aria-label="Permalink to &quot;II. Advanced Learning Directions&quot;">​</a></h2><h3 id="direction-1-cli-command-line-version" tabindex="-1">Direction 1: CLI (Command Line) Version <a class="header-anchor" href="#direction-1-cli-command-line-version" aria-label="Permalink to &quot;Direction 1: CLI (Command Line) Version&quot;">​</a></h3><p>If you&#39;re already familiar with the desktop app, try the command line version.</p><p><strong>Best for</strong>: Users who want more flexible control over Codex.</p><p><strong>What you&#39;ll learn</strong>:</p><ul><li>Install Codex CLI</li><li>Use command-line arguments to specify workspace and prompts</li><li>Write scripts to automate Codex calls</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Example command</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Help me refactor this project&#39;s code&quot;</span></span></code></pre></div><h3 id="direction-2-custom-skills" tabindex="-1">Direction 2: Custom Skills <a class="header-anchor" href="#direction-2-custom-skills" aria-label="Permalink to &quot;Direction 2: Custom Skills&quot;">​</a></h3><p>Solidify your common workflows into reusable skill templates.</p><p><strong>Best for</strong>: Users with fixed, repetitive work patterns.</p><p><strong>What you&#39;ll learn</strong>:</p><ul><li>Analyze your high-frequency work scenarios</li><li>Design the structure of skill templates</li><li>Use Codex to generate skill configuration files</li><li>Test and optimize skill effectiveness</li></ul><h3 id="direction-3-mcp-extensions" tabindex="-1">Direction 3: MCP Extensions <a class="header-anchor" href="#direction-3-mcp-extensions" aria-label="Permalink to &quot;Direction 3: MCP Extensions&quot;">​</a></h3><p>MCP (Model Context Protocol) is a protocol for connecting external tools and data sources.</p><p><strong>Best for</strong>: Users who want to integrate Codex with more tools.</p><p><strong>What you&#39;ll learn</strong>:</p><ul><li>Understand the basics of MCP</li><li>Configure MCP servers to connect to external APIs</li><li>Use MCP to extend Codex&#39;s capabilities</li></ul><h3 id="direction-4-multi-agent-collaboration" tabindex="-1">Direction 4: Multi-Agent Collaboration <a class="header-anchor" href="#direction-4-multi-agent-collaboration" aria-label="Permalink to &quot;Direction 4: Multi-Agent Collaboration&quot;">​</a></h3><p>Have multiple AI agents work on different things simultaneously.</p><p><strong>Best for</strong>: Users handling complex projects.</p><p><strong>What you&#39;ll learn</strong>:</p><ul><li>Design multi-agent collaboration workflows</li><li>Assign different tasks to different agents</li><li>Integrate output from multiple agents</li></ul><hr><h2 id="iii-practice-suggestions" tabindex="-1">III. Practice Suggestions <a class="header-anchor" href="#iii-practice-suggestions" aria-label="Permalink to &quot;III. Practice Suggestions&quot;">​</a></h2><h3 id="practice-a-little-every-day" tabindex="-1">Practice a Little Every Day <a class="header-anchor" href="#practice-a-little-every-day" aria-label="Permalink to &quot;Practice a Little Every Day&quot;">​</a></h3><ul><li>Spend 10-15 minutes each day using Codex to complete a small task</li><li>Record the prompts and results each time</li><li>Gradually build your own &quot;prompt library&quot;</li></ul><h3 id="join-the-community" tabindex="-1">Join the Community <a class="header-anchor" href="#join-the-community" aria-label="Permalink to &quot;Join the Community&quot;">​</a></h3><ul><li>Join Codex/ChatGPT user communities</li><li>Share your usage experiences and tips</li><li>Learn creative approaches from others</li></ul><h3 id="keep-learning" tabindex="-1">Keep Learning <a class="header-anchor" href="#keep-learning" aria-label="Permalink to &quot;Keep Learning&quot;">​</a></h3><ul><li>Follow OpenAI&#39;s official updates</li><li>Try new features and skills</li><li>Explore new application scenarios</li></ul><hr><h2 id="iv-summary" tabindex="-1">IV. Summary <a class="header-anchor" href="#iv-summary" aria-label="Permalink to &quot;IV. Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Learning Direction</th><th>Best For</th><th>Core Value</th></tr></thead><tbody><tr><td>CLI command line</td><td>Advanced users</td><td>More flexible automation control</td></tr><tr><td>Custom skills</td><td>Users with fixed workflows</td><td>Improve efficiency, reduce repetitive work</td></tr><tr><td>MCP extensions</td><td>Tech enthusiasts</td><td>Connect more external tools</td></tr><tr><td>Multi-agent collaboration</td><td>Complex project handlers</td><td>Parallel processing, improve efficiency</td></tr></tbody></table><hr><h2 id="v-closing-words" tabindex="-1">V. Closing Words <a class="header-anchor" href="#v-closing-words" aria-label="Permalink to &quot;V. Closing Words&quot;">​</a></h2><p>Congratulations on completing this course!</p><p>Remember, Codex is just a tool. What truly matters is what problems you solve with it. Don&#39;t be afraid to make mistakes — every &quot;that&#39;s not right&quot; is a learning opportunity.</p><p><strong>The most important thing — just start using it!</strong></p><hr><h2 id="vi-feedback-improvement" tabindex="-1">VI. Feedback &amp; Improvement <a class="header-anchor" href="#vi-feedback-improvement" aria-label="Permalink to &quot;VI. Feedback &amp; Improvement&quot;">​</a></h2><p>If you found this course helpful, or have any suggestions for improvement, please feel free to fill out our <a href="./../../appendix/feedback.html">Feedback Form</a>.</p>`,48)])])}const m=t(n,[["render",r]]);export{p as __pageData,m as default};
